public static double calculateAverageBalance(List<Double> closingBalances) {
    if (closingBalances == null) {
        throw new IllegalArgumentException("closingBalances list cannot be null");
    }
    int size = closingBalances.size();
    if (size == 0) {
        throw new IllegalArgumentException("closingBalances list cannot be empty");
    }
    double sum = 0.0;
    for (Double balance : closingBalances) {
        if (balance == null) {
            throw new IllegalArgumentException("closingBalances list cannot contain null elements");
        }
        sum += balance;
    }
    return sum / size;
}

