public static int calculateTimeNeeded(int N) {
    // If there are fewer than 3 people, no time is needed to reverse the seating order.
    if (N < 3) {
        return 0;
    }
    // The time needed grows linearly: 2 minutes for 4 people, 4 minutes for 5 people, 6 minutes for 6 people, etc.
    // This follows the formula: time = 2 * (N - 3).
    // Use long to avoid overflow for very large N, then cast back to int.
    long time = 2L * (N - 3);
    return (int) Math.min(time, Integer.MAX_VALUE);
}

