public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Normalize strings: treat null as empty string
    List<String> normalized = new ArrayList<>();
    for (String s : strings) {
        normalized.add(s == null ? "" : s);
    }
    String base = normalized.get(0);
    if (base.isEmpty()) {
        return 0;
    }
    int baseLen = base.length();
    // Iterate lengths from longest to shortest
    for (int len = baseLen; len >= 1; len--) {
        for (int start = 0; start <= baseLen - len; start++) {
            String sub = base.substring(start, start + len);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean allMatch = true;
            for (String s : normalized) {
                if (s.indexOf(sub) == -1 && s.indexOf(rev) == -1) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

