public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 == 0) {
            int half = n / 2;
            Integer halfCount = freq.get(half);
            if (halfCount != null) {
                if (half == n) { // n == 0
                    if (halfCount > 1) {
                        count++;
                    }
                } else {
                    count++;
                }
            }
        }
    }
    return count;
}

