public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic input validation
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }
    if (paths == null) {
        return "cannot be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p == null || p.length != 4) {
            continue; // skip invalid path entries
        }
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue; // skip out-of-bounds paths
        }
        String key1 = x1 + "," + y1;
        String key2 = x2 + "," + y2;
        adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    String startKey = sx + "," + sy;
    String endKey = ex + "," + ey;

    // BFS to find connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.get(current);
        if (neighbors == null) {
            continue;
        }
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

