public static String convertDatesToWeekdays(String date) {
    try {
        java.time.format.DateTimeFormatter inputFormatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, inputFormatter);
        java.time.format.TextStyle textStyle = java.time.format.TextStyle.FULL;
        java.util.Locale locale = java.util.Locale.ENGLISH;
        String monthName = localDate.getMonth().getDisplayName(textStyle, locale);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.getDayOfWeek().getDisplayName(textStyle, locale);
        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (Exception e) {
        return "Invalid date";
    }
}

