public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int k = n / 20; // 5% of n, integer division
    if (k == 0) {
        // If k is zero, no trimming needed
        long total = 0;
        for (int val : arr) {
            total += val;
        }
        return total / (double) n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (double) (n - 2 * k);
}

