public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder();
    while (!map.isEmpty()) {
        // Increasing phase
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        result.append(last);
        if (entry.getValue() == 1) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue() - 1);
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> next = map.higherEntry(last);
            if (next == null) {
                break;
            }
            last = next.getKey();
            result.append(last);
            if (next.getValue() == 1) {
                map.remove(last);
            } else {
                map.put(last, next.getValue() - 1);
            }
        }
        if (map.isEmpty()) {
            break;
        }
        // Decreasing phase
        java.util.Map.Entry<Character, Integer> entry2 = map.lastEntry();
        last = entry2.getKey();
        result.append(last);
        if (entry2.getValue() == 1) {
            map.remove(last);
        } else {
            map.put(last, entry2.getValue() - 1);
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> prev = map.lowerEntry(last);
            if (prev == null) {
                break;
            }
            last = prev.getKey();
            result.append(last);
            if (prev.getValue() == 1) {
                map.remove(last);
            } else {
                map.put(last, prev.getValue() - 1);
            }
        }
    }
    return result.toString();
}

