public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int prevPrev = 0; // cost to reach step 0
    int prev = 0;     // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int cur;
        if (i == n) {
            // reaching the top: can come from step n-1 or n-2
            cur = Math.min(prev + cost[n - 1], prevPrev + cost[n - 2]);
        } else {
            // reaching step i
            cur = Math.min(prev + cost[i - 1], prevPrev + cost[i - 2]);
        }
        prevPrev = prev;
        prev = cur;
    }
    return prev;
}

