public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    long total = 1L << k;
    if (n < total) {
        return false;
    }
    long mask = (1L << k) - 1;
    if (k <= 20) {
        int totalInt = (int) total;
        boolean[] seen = new boolean[totalInt];
        int count = 0;
        long curr = 0;
        for (int i = 0; i < n; i++) {
            curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                int idx = (int) curr;
                if (!seen[idx]) {
                    seen[idx] = true;
                    count++;
                    if (count == totalInt) {
                        return true;
                    }
                }
            }
        }
        return false;
    } else {
        java.util.HashSet<Long> seen = new java.util.HashSet<>();
        long curr = 0;
        for (int i = 0; i < n; i++) {
            curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                if (seen.add(curr)) {
                    if (seen.size() == total) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

