public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int max = 0;
    // Local class to hold state for DFS
    class State {
        int pos;
        Set<String> used;
        int count;
        State(int pos, Set<String> used, int count) {
            this.pos = pos;
            this.used = used;
            this.count = count;
        }
    }
    Deque<State> stack = new ArrayDeque<>();
    stack.push(new State(0, new HashSet<>(), 0));
    while (!stack.isEmpty()) {
        State cur = stack.pop();
        int pos = cur.pos;
        Set<String> used = cur.used;
        int count = cur.count;
        if (pos == n) {
            if (count > max) {
                max = count;
            }
            continue;
        }
        for (int end = pos + 1; end <= n; end++) {
            String sub = s.substring(pos, end);
            if (!used.contains(sub)) {
                Set<String> newUsed = new HashSet<>(used);
                newUsed.add(sub);
                stack.push(new State(end, newUsed, count + 1));
            }
        }
    }
    return max;
}

