public String getSmallestString(int n, int k) {
    // Validate input: the minimum possible sum is n (all 'a'), maximum is 26*n (all 'z')
    if (k < n || k > 26 * n) {
        return "";
    }
    char[] result = new char[n];
    // Start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // how much we need to add to reach k
    // Distribute the remaining value from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase by at most 25 ('a'->'z')
        result[i] = (char) (result[i] + add);
        remaining -= add;
    }
    return new String(result);
}

