public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Ensure low is at least 0 because stepping numbers are non-negative
    int start = Math.max(low, 0);
    Queue<Long> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= start) {
            result.add((int) num);
        }
        // Do not generate children for 0 to avoid leading zeros
        if (num == 0) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

