public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long nLong = n;
    while (factor <= nLong) {
        long high = nLong / (factor * 10);
        long cur = (nLong / factor) % 10;
        long low = nLong % factor;
        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

