public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // For positive integers, a number is a power of two if it has exactly one bit set.
    // This is true when n & (n - 1) == 0.
    return (n & (n - 1)) == 0;
}

