public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) {
        return 0;
    }
    int max = 0;
    int[][] dpH = new int[m][n];
    int[][] dpV = new int[m][n];
    int[][] dpD = new int[m][n];
    int[][] dpAD = new int[m][n];
    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            continue; // treat missing rows as all zeros
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                         Math.max(dpD[i][j], dpAD[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpAD[i][j] = 0;
            }
        }
    }
    return max;
}

