public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    // Precompute perfect squares up to 2*max(A)
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    // Memoization map: key = (mask << 32) | (lastIndex+1)
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int fullMask = (1 << n) - 1;
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int lastIndex) {
            long key = (((long) mask) << 32) | (lastIndex + 1);
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            if (mask == fullMask) {
                return 1;
            }
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                // Skip duplicates: if same value as previous and previous not used
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                if (lastIndex == -1 || isSquare[A[i] + A[lastIndex]]) {
                    count += applyAsInt(mask | (1 << i), i);
                }
            }
            memo.put(key, count);
            return count;
        }
    };
    return dfs.applyAsInt(0, -1);
}

