public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    int maxSum = m + n - 2;
    for (int s = 0; s <= maxSum; s++) {
        if (s % 2 == 0) {
            // bottom to top
            int row = Math.min(s, m - 1);
            int col = s - row;
            while (row >= 0 && col < n) {
                result[idx++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            // top to bottom
            int row = Math.max(0, s - (n - 1));
            int col = s - row;
            while (row < m && col >= 0) {
                result[idx++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

