public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] arr = new char[n];
    // Mapping function for digits
    java.util.function.Function<Character, Character> map = d -> {
        switch (d) {
            case '0': return '0';
            case '1': return '1';
            case '6': return '9';
            case '8': return '8';
            case '9': return '6';
            default: return '?';
        }
    };
    // Recursive helper
    java.util.function.BiConsumer<Integer, Integer> dfs = new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer pos, Integer dummy) {
            int left = pos;
            int right = n - 1 - pos;
            if (left > right) {
                result.add(new String(arr));
                return;
            }
            if (left == right) { // middle position for odd length
                char[] middleDigits = {'0', '1', '8'};
                for (char d : middleDigits) {
                    arr[left] = d;
                    accept(pos + 1, 0);
                }
            } else {
                char[] digits = {'0', '1', '6', '8', '9'};
                for (char d : digits) {
                    if (left == 0 && n > 1 && d == '0') {
                        continue; // no leading zero for length > 1
                    }
                    arr[left] = d;
                    arr[right] = map.apply(d);
                    accept(pos + 1, 0);
                }
            }
        }
    };
    dfs.accept(0, 0);
    return result;
}

