public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    // If n is a perfect square, return 1 immediately
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    int[] dp = new int[n + 1];
    // Initialize dp array with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

